fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    // Create a row vector of length v.len()
    // Set the i-th element to v[i], others to 0.0
    let n = v.len();
    let mut row = Vec::with_capacity(n);
    for j in 0..n {
        if j == i {
            row.push(v[i]);
        } else {
            row.push(0.0);
        }
    }
    row
}

fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    // For each index i, create a row with v[i] on diagonal, 0.0 elsewhere
    let n = v.len();
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        matrix.push(create_row(&v, i));
    }
    matrix
}